package org.apache.commons.io.input;



public abstract class ProxyInputStream extends FilterInputStream
{

    public ProxyInputStream(InputStream proxy)
    {
        super(proxy);
    }

    public int read()
        throws IOException
    {
        int b;
        beforeRead(1);
        b = in.read();
        afterRead(b == -1 ? -1 : 1);
        return b;
        IOException e;
        e;
        handleIOException(e);
        return -1;
    }

    public int read(byte bts[])
        throws IOException
    {
        int n;
        beforeRead(bts == null ? 0 : bts.length);
        n = in.read(bts);
        afterRead(n);
        return n;
        IOException e;
        e;
        handleIOException(e);
        return -1;
    }

    public int read(byte bts[], int off, int len)
        throws IOException
    {
        int n;
        beforeRead(len);
        n = in.read(bts, off, len);
        afterRead(n);
        return n;
        IOException e;
        e;
        handleIOException(e);
        return -1;
    }

    public long skip(long ln)
        throws IOException
    {
        return in.skip(ln);
        IOException e;
        e;
        handleIOException(e);
        return 0L;
    }

    public int available()
        throws IOException
    {
        return super.available();
        IOException e;
        e;
        handleIOException(e);
        return 0;
    }

    public void close()
        throws IOException
    {
        try
        {
            in.close();
        }
        catch(IOException e)
        {
            handleIOException(e);
        }
    }

    public synchronized void mark(int readlimit)
    {
        in.mark(readlimit);
    }

    public synchronized void reset()
        throws IOException
    {
        try
        {
            in.reset();
        }
        catch(IOException e)
        {
            handleIOException(e);
        }
    }

    public boolean markSupported()
    {
        return in.markSupported();
    }

    protected void beforeRead(int i)
        throws IOException
    {
    }

    protected void afterRead(int i)
        throws IOException
    {
    }

    protected void handleIOException(IOException e)
        throws IOException
    {
        throw e;
    }
}
