package cn.abovesky.shopping.util;












public class CompressImage {
    private File file = null; private String input;
    private String output;
    private InputStream inputStream;
    private int outputWidth = 100; private int outputHeight = 100; private boolean proportion = true; public CompressImage() { input = "";
        output = "";
        outputWidth = 100;
        outputHeight = 100;
    }

    public String getOutput() {
        return output;
    }

    public void setOutput(String output) {
        this.output = output;
    }

    public String getInput() {
        return input;
    }

    public void setInput(String input) {
        this.input = input;
    }

    public void setOutputWidth(int outputWidth) {
        this.outputWidth = outputWidth;
    }
    public void setOutputHeight(int outputHeight) {
        this.outputHeight = outputHeight;
    }
    public void setWidthAndHeight(int width, int height) {
        this.outputWidth = width;
        this.outputHeight = height;
    }

    public long getPicSize(String path) {
        file = new File(path);
        return file.length();
    }

    public boolean compressPic() {
        try {
            file = new File(input);
            if (!file.exists()) {
                return false;
            }
            Image img = ImageIO.read(file);
            if (img.getWidth(null) == -1) {
                return false;
            } else {
                int newWidth; int newHeight;
                if (this.proportion == true) {
                    double rate1 = ((double) img.getWidth(null)) / (double) outputWidth + 0.1;
                    double rate2 = ((double) img.getHeight(null)) / (double) outputHeight + 0.1;
                    double rate = rate1 > rate2 ? rate1 : rate2;
                    newWidth = (int) (((double) img.getWidth(null)) / rate);
                    newHeight = (int) (((double) img.getHeight(null)) / rate);
                } else {
                    newWidth = outputWidth; newHeight = outputHeight; }
                BufferedImage tag = new BufferedImage((int) newWidth, (int) newHeight, BufferedImage.TYPE_INT_RGB);

                tag.getGraphics().drawImage(img.getScaledInstance(newWidth, newHeight, Image.SCALE_SMOOTH), 0, 0, null);
                FileOutputStream out = new FileOutputStream(output);
                JPEGImageEncoder encoder = JPEGCodec.createJPEGEncoder(out);
                encoder.encode(tag);
                out.close();
            }
        } catch (IOException ex) {
            ex.printStackTrace();
        }
        return true;
    }

    public boolean compressPicWithInputStream() {
        try {
            Image img = ImageIO.read(inputStream);
            if (img.getWidth(null) == -1) {
                return false;
            } else {
                int newWidth; int newHeight;
                if (this.proportion == true) {
                    double rate1 = ((double) img.getWidth(null)) / (double) outputWidth + 0.1;
                    double rate2 = ((double) img.getHeight(null)) / (double) outputHeight + 0.1;
                    double rate = rate1 > rate2 ? rate1 : rate2;
                    newWidth = (int) (((double) img.getWidth(null)) / rate);
                    newHeight = (int) (((double) img.getHeight(null)) / rate);
                } else {
                    newWidth = outputWidth; newHeight = outputHeight; }
                BufferedImage tag = new BufferedImage((int) newWidth, (int) newHeight, BufferedImage.TYPE_INT_RGB);

                tag.getGraphics().drawImage(img.getScaledInstance(newWidth, newHeight, Image.SCALE_SMOOTH), 0, 0, null);
                FileOutputStream out = new FileOutputStream(output);
                JPEGImageEncoder encoder = JPEGCodec.createJPEGEncoder(out);
                encoder.encode(tag);
                out.close();
            }
        } catch (IOException ex) {
            ex.printStackTrace();
        }
        return true;
    }

    public boolean compressPic(String input, String output, int width, int height, boolean gp) {
        this.input = input;
        this.output = output;
        setWidthAndHeight(width, height);
        this.proportion = gp;
        return compressPic();
    }

    public boolean compressPic(InputStream inputStream, String output, int width, int height, boolean gp) {
        this.inputStream = inputStream;
        this.output = output;
        setWidthAndHeight(width, height);
        this.proportion = gp;
        return compressPicWithInputStream();
    }
}
