        }catch(Exception e){
            e.printStackTrace();
        }
        TokenRequest r=new TokenRequest();
        try {
            r.fromJson(json);
            System.out.println(r.getBody().getTicket());
        } catch (JsonMappingException e) {
            e.printStackTrace();
        } catch (JsonGenerationException e) {
            e.printStackTrace();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
