   private int root;
   private String path;

   public native Object getValue(String name);

   public native void setValue(String name, Object value);

   public Win32RegKey(int theRoot, String thePath)
   {
      root = theRoot;
      path = thePath;
   }

   public Enumeration<String> names()
   {
