   public void paintComponent(Graphics g)
   {
      Graphics2D g2 = (Graphics2D) g;

      double leftX = 100;
      double topY = 100;
      double width = 200;
      double height = 150;

      Rectangle2D rect = new Rectangle2D.Double(leftX, topY, width, height);
      g2.draw(rect);

      Ellipse2D ellipse = new Ellipse2D.Double();
      ellipse.setFrame(rect);
