            throw new IllegalArgumentException("æ²¡ææå®æå¡å¨");
        String serverName = args[0];
        String ip = Config.getServerIp(serverName);
        int port = Config.getServerPort(serverName);
        new Gatewayserver(ip, port, serverName).start();

    }
}
