package com.nercis.isscp.idl;






public enum PlotsType implements org.apache.thrift.TEnum {
  equalsType(0),
  staticType(1),
  dynamicType(2),
  virusType(3),
  sensitiveType(4),
  commonsType(5);

  private final int value;

  private PlotsType(int value) {
    this.value = value;
  }

  public int getValue() {
    return value;
  }

  public static PlotsType findByValue(int value) { 
    switch (value) {
      case 0:
        return equalsType;
      case 1:
        return staticType;
      case 2:
        return dynamicType;
      case 3:
        return virusType;
      case 4:
        return sensitiveType;
      case 5:
        return commonsType;
      default:
        return null;
    }
  }
}
