            return false;

        DownloadTaskInfo a = (DownloadTaskInfo) obj;
        if (!super.equals(a))
            return false;

        if (a.pathInRepo == null)
            return false;

        return a.pathInRepo.equals(this.pathInRepo) && a.fileSize == this.fileSize && a.finished == this.finished;
