            gameView.hero.father = gameView;
            gameView.hero.initAnimationSegment(GameView.heroAnimationSegments);gameView.hero.startAnimation();gameView.hero.hgt = new HeroGoThread(gameView,gameView.hero);
            gameView.drawThread.setIsViewOn(true);

