    int startX = 25;

    ArrayList<Skill> items = new ArrayList<Skill>();static Bitmap threeBitmap;static Bitmap panel_back;static Bitmap selectBackground;static Bitmap buttonBackGround;static Bitmap upBitmap;static Bitmap downBitmap;static Bitmap menuTitle;static Bitmap logo;
    static Bitmap addBitmap;static Bitmap cutBitmap;HashMap<Integer,Skill> skills;
    int number = 1;
    Paint paint;
    public UseSkillView(GameView gameView) {
        this.gameView = gameView;
        paint = new Paint();
        paint.setARGB(255, 42, 48, 103);paint.setAntiAlias(true);initData();}

    public static void initBitmap(Resources r){Bitmap menu_item = BitmapFactory.decodeResource(r, R.drawable.buttons); 
        threeBitmap = Bitmap.createBitmap(menu_item, 60, 0, 90, 30);
        buttonBackGround = Bitmap.createBitmap(menu_item, 0, 0, 60, 30);
        upBitmap = Bitmap.createBitmap(menu_item, 210, 15, 15, 15);
        downBitmap = Bitmap.createBitmap(menu_item, 210, 0, 15, 15);
        addBitmap = Bitmap.createBitmap(menu_item, 225, 15, 15, 15);
        cutBitmap = Bitmap.createBitmap(menu_item, 225, 0, 15, 15);
        menu_item = null;panel_back = BitmapFactory.decodeResource(r, R.drawable.panel_back);
        logo = BitmapFactory.decodeResource(r, R.drawable.logo);
        selectBackground = BitmapFactory.decodeResource(r, R.drawable.select_back);
        menuTitle = BitmapFactory.decodeResource(r, R.drawable.menu_title);
    }

    public void initData(){skills = gameView.hero.getHeroSkill();
        items.clear();
        Set<Integer> keySet = skills.keySet();
        Iterator<Integer> ii = keySet.iterator();

        while(ii.hasNext()){
            Skill s = (Skill)skills.get((Integer)ii.next());
            if(s.getSkillType() == 1){
                items.add(s);
            }
        }
    }
    public void onDraw(Canvas canvas){canvas.drawBitmap(panel_back, 0, 0, paint);  
        canvas.drawBitmap(threeBitmap, 212, 15, paint);
        canvas.drawBitmap(logo, 15, 16, paint);paint.setTextSize(23);canvas.drawText("Ê¹ÓÃ¼ÆÄ±", 50, 40, paint);
        paint.setTextSize(18);canvas.drawBitmap(menuTitle, 10, 70, paint);
        canvas.drawText("¼¼ÄÜÃû", 15, 90, paint);
        canvas.drawText("µÈ¼¶", 120, 90, paint);
        canvas.drawText("ÏûºÄ", 200, 90, paint);


        for(int i=0; i<items.size(); i++){
            canvas.drawText(items.get(i).getName(), 15, startY +35 + 30*i, paint);
            canvas.drawText(items.get(i).getProficiencyLevel()+"", 120, startY +35 + 30*i, paint);
            canvas.drawText(items.get(i).getStrengthCost()+"", 200, startY +35+ 30*i, paint);       
            if(items.get(i) instanceof SuiXinBuSkill){canvas.drawText("("+number+")", 75, startY +35 + 30*i, paint);
                canvas.drawBitmap(addBitmap, 250, startY+35+30*i-15, paint);
                canvas.drawBitmap(cutBitmap, 270, startY+35+30*i-15, paint);                
            }
        }

        canvas.drawBitmap(selectBackground, 10, startY + 35 + 30*selectI - 22, paint);
        canvas.drawBitmap(buttonBackGround, 130, 430, paint);canvas.drawText("Ê¹ÓÃ", 142, 452, paint);
    }

    public boolean onTouchEvent(MotionEvent event){
        if(event.getAction() == MotionEvent.ACTION_DOWN){int x = (int) event.getX();
            int y = (int) event.getY();
            if(x>212 && x<242 && y>15 && y<45){if(items.size() == 0){
                    return true;
                }           
                selectI++;
                if(selectI > items.size()-1){ 
                    selectI = items.size()-1;
                }   
            }
            else if(x>243 && x<273 && y>15 && y<45){if(items.size() == 0){
                    return true;
                }
                selectI--;
                if(selectI < 0){
                    selectI = 0;
                }
            }
            else if(x>274 && x<304&& y>15 && y<45){gameView.setStatus(0);
            }
            if(x>130 && x<190 && y>430 && y<460){if(items.size() == 0){
                    return true;
                }
                Skill skill = items.get(selectI);

                if(skill.calculateResult() == -1){}
                else {gameView.suiXinBu = number;
                    skill.useSkill(0);}
                selectI = 0;
                gameView.setStatus(0);
            }
            else if(x>252 && x<267 && y>111 && y<126){this.number++;
                if(number > 6){
                    number = 6;
                }
            }
            else if(x>271 && x<286 && y>111 && y<126){this.number--;
                if(number <1 ){
                    number = 1;
                }
            }
        }
        return true;
    }
}
