package cn.itcast_03;

public class ArgsDemo {
    public static void main(String[] args) {
int a = 10;
        int b = 20;
        int result = sum(a, b);
        System.out.println(result);

        int c = 30;
        result = sum(a, b, c);
        System.out.println(result);

        int d = 40;
        result = sum(a, b, c, d);
        System.out.println(result);

        result = sum(10, 20, 30, 40, 50);
        System.out.println(result);
        result = sum(10, 20, 30, 40, 50, 60, 70, 80, 90);
        System.out.println(result);
    }

    public static int sum(int b,int... a) {
        int result = 0;
        for (int i : a) {
            result += i;
        }
        return result;
    }


